import django.db.models.deletion
from django.db import migrations, models

# Ideas and planned plans become one status, Planned. Every stay, transport and activity that was an
# idea goes on its trip's checklist marked "to review", linked to it, so nothing is lost in the merge.

REVIEW_NOTE = "Was an idea. Ideas and planned plans are now both Planned: check it's still wanted, and its estimated cost."


def ideas_to_planned(apps, schema_editor):
    ChecklistItem = apps.get_model("journeys", "ChecklistItem")
    for model, label in (("Stay", lambda s: f"Stay: {s.label}"),
                         ("Leg", lambda l: f"{l.get_mode_display()}: {l.origin.name} → {l.destination.name}"),
                         ("Item", lambda i: f"Activity: {i.title}")):
        Model = apps.get_model("journeys", model)
        for plan in Model.objects.filter(status="idea"):
            trip_id = plan.day.trip_id if model == "Item" else plan.trip_id
            ChecklistItem.objects.create(trip_id=trip_id, text=f"Review {label(plan)}"[:200], notes=REVIEW_NOTE, to_review=True,
                                         **{model.lower() if model != "Leg" else "leg": plan})
            plan.status = "planned"
            plan.save(update_fields=["status"])




